import hashlib,json,re
def fp(k): return hashlib.sha256(k.encode()).hexdigest()[:8]
# ob_live_keys.txt: nomor -> key
live=[]
for l in open("ob_live_keys.txt"):
    m=re.match(r"\s*(\d+)\.\s*(sk-obs1_[A-Za-z0-9_-]+)",l)
    if m: live.append((int(m.group(1)),m.group(2)))
# ob_accounts.txt: id -> key
acc=[]
for n,l in enumerate(open("ob_accounts.txt"),1):
    p=[x.strip() for x in l.split("|")]
    if len(p)>=2 and p[1].startswith("sk-obs1"): acc.append((n,p[0],p[1]))
print(f"live={len(live)} akun={len(acc)}")
bykey={fp(k):(n,i) for n,i,k in acc}
print("\nposisi 1-5 di ob_live_keys.txt:")
for num,k in live[:5]:
    f=fp(k); hit=bykey.get(f)
    print(f"  #{num} fp={f} -> akun baris {hit[0]}, ID {hit[1]}" if hit else f"  #{num} fp={f} -> tidak cocok")
